targets.query:
// Derived from the time range, like the Suricata dashboard: ~96 buckets
// however far you zoom, floored at the service's 60s window, below which
// there is nothing finer to show.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "wids_alert" and r._field == "count")
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> group(columns: ["severity", "severity_name"])
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "severity_name"])

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "wids_alert")
  // Alerts are throttled at the source, so the pivot runs on a few hundred
  // rows at most -- it is the one non-pushdown step here.
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> limit(n: 200)
  |> keep(columns: ["_time", "severity", "alert", "bssid", "ssid", "source", "count", "detail"])

// Derived from the time range, like the Suricata dashboard: ~96 buckets
// however far you zoom, floored at the service's 60s window, below which
// there is nothing finer to show.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "wids")
  |> filter(fn: (r) => r._field == "frames" or r._field == "fcs_errors"
      or r._field == "wrong_encap" or r._field == "udp_drops" or r._field == "malformed")
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "_field"])
